import ifcopenshell
model = ifcopenshell.open('output/model.ifc')

chw = model.by_type('IfcFlowSegment')
print(f'Total CHW segments: {len(chw)}')
seen = {}
for e in chw:
    pset = [rel.RelatingPropertyDefinition for rel in model.by_type('IfcRelDefinesByProperties') if e in rel.RelatedObjects][0]
    props = {prop.Name: prop.NominalValue.wrappedValue if prop.NominalValue else None for prop in pset.HasProperties}
    key = (props.get('StartX'), props.get('StartY'), props.get('StartZ'), props.get('EndX'), props.get('EndY'), props.get('EndZ'))
    if key in seen:
        seen[key].append(e.Name)
    else:
        seen[key] = [e.Name]

for key, names in seen.items():
    if len(names) > 1:
        print(f'DUPLICATE: {names}')
        print(f'  {key}')

# Also check for segments with None coordinates (underfloor)
for e in chw:
    pset = [rel.RelatingPropertyDefinition for rel in model.by_type('IfcRelDefinesByProperties') if e in rel.RelatedObjects][0]
    props = {prop.Name: prop.NominalValue.wrappedValue if prop.NominalValue else None for prop in pset.HasProperties}
    if props.get('StartX') is None:
        print(f'Underfloor element in CHW: {e.Name}')

print()
# Check actual CHW segments only (those with DCM_CHW_PIPE pset)
actual_chw = []
for e in chw:
    pset = [rel.RelatingPropertyDefinition for rel in model.by_type('IfcRelDefinesByProperties') if e in rel.RelatedObjects][0]
    if 'CHW_PIPE' in pset.Name:
        actual_chw.append(e)
print(f'Actual CHW pipe segments: {len(actual_chw)}')
